// Minimal read-only server exposing registry/ with npm registry API
// semantics: GET /<name> -> packument JSON, GET /<name>/<file> -> tarball,
// GET /-/ping -> {}. Binds 127.0.0.1 only. Publishing is done by writing
// registry files (registry-cli.js), not over HTTP.
const http = require("http");
const fs = require("fs");
const path = require("path");

const REG = path.resolve(process.env.REGISTRY_DIR || path.join(__dirname, "registry"));
const PORT = Number(process.argv[2] || 4873);
const MIME = { ".json": "application/json; charset=utf-8", ".tgz": "application/octet-stream" };

http
  .createServer((req, res) => {
    const pathname = decodeURIComponent(new URL(req.url, "http://localhost").pathname);
    if (pathname === "/-/ping") {
      res.writeHead(200, { "Content-Type": MIME[".json"] });
      return res.end("{}");
    }
    const segs = pathname.split("/").filter(Boolean);
    let file = null;
    if (segs.length === 1) file = path.join(REG, segs[0], "index.json");
    else if (segs.length === 2) file = path.join(REG, ...segs);
    if (file) {
      file = path.resolve(file);
      if (file.startsWith(REG + path.sep) && fs.existsSync(file) && fs.statSync(file).isFile()) {
        const stat = fs.statSync(file);
        res.writeHead(200, {
          "Content-Type": MIME[path.extname(file)] || "text/plain",
          "Content-Length": stat.size,
        });
        return fs.createReadStream(file).pipe(res);
      }
    }
    res.writeHead(404, { "Content-Type": MIME[".json"] });
    res.end(JSON.stringify({ error: "Not Found" }));
  })
  .listen(PORT, "127.0.0.1", () => {
    console.log(`local registry serving ${REG} at http://127.0.0.1:${PORT}`);
  });
